&DefaultButton;




			function dir$dmlvtc1(p) {
				this.constructor(p);
				document._dir = p;
			}

			dir$dmlvtc1.prototype = new DirEvent();
			dir$dmlvtc1.prototype.afterInit = function(renderType) {
				var p = this._dir;

				let uploadedImage = null;
				let isViewMode = (p.options.action === 'VIEW');

				// Hàm cập nhật preview & nút xoá
				function updateMainImagePreview() {
					const mainImagePreview = document.getElementById('mainImagePreview');
					const addImageLabel = document.getElementById('addImageLabel');
					mainImagePreview.innerHTML = '';

					if (!uploadedImage) {
						mainImagePreview.textContent = 'Chưa có ảnh';
						// Chỉ hiển thị nút upload khi không phải VIEW
						addImageLabel.style.display = isViewMode ? 'none' : 'flex';
					} else {
						const imgTag = document.createElement('img');
						imgTag.src = uploadedImage.url;
						if (uploadedImage.srcset) imgTag.srcset = uploadedImage.srcset;
						mainImagePreview.appendChild(imgTag);

						// Nút xoá (chỉ hiển thị khi không phải VIEW)
						if (!isViewMode) {
							const removeBtn = document.createElement('button');
							removeBtn.innerText = '❌';
							removeBtn.className = 'delete-btn';
							removeBtn.onclick = deleteCurrentImage;
							removeBtn.style.position = 'absolute';
							removeBtn.style.top = '4px';
							removeBtn.style.right = '4px';
							removeBtn.style.zIndex = 1;
							mainImagePreview.appendChild(removeBtn);
						}
						// Ẩn nút upload nếu đã có ảnh hoặc đang VIEW
						addImageLabel.style.display = (!isViewMode && !uploadedImage) ? 'flex' : 'none';
					}
					// Vô hiệu hóa vùng preview khi VIEW
					mainImagePreview.classList.toggle('view-mode', isViewMode);
				}

				// Xử lý upload ảnh (chỉ cho thao tác nếu không phải VIEW)
				document.getElementById('addImageLabel').onclick = function() {
					if (isViewMode) return;
					document.getElementById('imagePicker').click();
				};

				document.getElementById('imagePicker').addEventListener('change', async function() {
					if (isViewMode) return; // Không cho thao tác khi VIEW

					const file = this.files?.[0];
					if (!file) return;
					const formData = new FormData();
					formData.append('file', file);

					try {
						const res = await fetch('http://localhost:5034/api/upload', {
							method: 'POST',
							body: formData
						});
						if (!res.ok) {
							const errMsg = await res.text();
							alert('Lỗi upload: ' + errMsg);
							return;
						}
						const data = await res.json();

						// Nếu đã có ảnh, xóa row cũ
						const rows = p.grid(0).data.obj.Rows;
						if (rows.length > 0) {
							p.deleteRow(0, 0);
						}
						// Add row mới
						const dataRow = [
							data.id,    // media_id
							'',
							data.url,   // url
							data.srcset // srcset
						];
						p.addRow(dataRow, 0);

						uploadedImage = data;
						updateMainImagePreview();
						this.value = '';
					} catch (error) {
						alert('Upload error');
					}
				});

				// Xử lý xoá ảnh (chỉ cho thao tác nếu không phải VIEW)
				async function deleteCurrentImage() {
					if (!uploadedImage || isViewMode) return;
					const id = uploadedImage.id;
					try {
						await fetch(`http://localhost:5034/file/${id}`, { method: 'DELETE' });
					} catch (err) {
						alert('Không thể xoá server: ' + err);
					}
					// Xóa row
					const rows = p.grid(0).data.obj.Rows;
					if (rows.length > 0 && rows[0][0] === id) {
						p.deleteRow(0, 0);
					}
					uploadedImage = null;
					updateMainImagePreview();
				}

				// Khi vào EDIT/VIEW: nạp lại từ table
				function loadImageFromTable() {
					const rows = p.grid(0).data.obj.Rows;
					if (rows && rows.length > 0) {
						const r = rows[0];
						uploadedImage = {
							id: r[0],
							url: r[2],
							srcset: r[3]
						};
					} else {
						uploadedImage = null;
					}
					updateMainImagePreview();
				}

				// Khi NEW/EDIT thì cho thao tác, VIEW thì khóa
				if (p.options.action === 'EDIT' || p.options.action === 'VIEW') {
					loadImageFromTable();
				} else {
					updateMainImagePreview();
				}

				// Tự động khóa mã khi NEW (nếu cần)
				if (p.options.action == 'NEW') {
					p.request('request_code_unit', '', '', function(pp, d, run) {
						if (run) {
							p.setDisabled('ma_lvtc1', true);
						}
					});
				}
			};







			.main-preview {
				min-width: 80px; width: 80px; max-width: 80px;
				height: 80px; display: flex; align-items: center; justify-content: center;
				font-size: 12px; color: #666; background-color: #fafafa;
				border-radius: 8px; background-size: cover; background-position: center;
				background-repeat: no-repeat; border: 2px dashed #999; position: relative;
			}
			.main-preview img {
				width: 100%; height: 100%; object-fit: contain; border-radius: 8px; display: block;
			}
			.delete-btn {
				position: absolute; top: 4px; right: 4px; width: 20px; height: 20px;
				background: rgba(255, 0, 0, 0.8); color: white; border: none; border-radius: 50%;
				cursor: pointer; font-size: 14px; line-height: 20px; text-align: center; z-index: 1;
			}
			#addImageLabel {
				border: 2px dashed #aaa; border-radius: 6px; display: flex; flex-direction: column;
				justify-content: center; align-items: center; width: 80px; height: 80px; cursor: pointer;
				font-size: 12px; color: #999; background: #fafafa; margin: 0;
			}
			#addImageLabel:hover {
				border-color: #ee4d2d; background: #ee4d2d08;
			}
			.edit-label.edit-title {
				display: flex; align-items: center; color: #333; margin-bottom: 12px; font-weight: 600;
			}
			.mandatory { color: #ee4d2d; font-size: 14px; }
			.mandatory-icon { margin-right: 3px; vertical-align: middle; }
			.view-mode { pointer-events: none; opacity: 0.6; }







				DECLARE @ma_unit VARCHAR(32);
				SELECT @ma_unit = ma_unit FROM sysunit WHERE unit_id = @@unit;

				SELECT 
					@ma_unit + 'C1' + RIGHT('00000' + CAST(ISNULL(MAX(CAST(SUBSTRING(ma_lvtc1, LEN(@ma_unit) + 3, 5) AS INT)), 0) + 1 AS VARCHAR), 5) AS [!ma_lvtc1]
				FROM dmlvtc1
				WHERE ma_lvtc1 LIKE @ma_unit + 'C1%';							






				select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @unit_id = @@unit;
				--exec ISWIFTStoredGetIdentityNumber '', '@@table', @ma_lvtc1 output;	







				update @dmvtmedia set ma_vt = @ma_lvtc1, user_id0 = @user_id0, user_id2 = @user_id2, datetime0 = getdate(), datetime2 = getdate(), unit_id = @unit_id
				delete dmvtmedia where ma_vt = @ma_lvtc1
				insert dmvtmedia select * from @dmvtmedia
